hunks.replacementText:
  html[data-nav-stage-rail="true"] .cards { margin-top: 0.375rem; }
}

/* Fixed legacy portraits retain the 6px text floor and 32px dock controls.
   A short desktop spends less space on outer chrome, not authored geometry. */
@media screen and (min-width: 1024px) and (max-height: 920px) {
  html[data-reader-layout="adaptive"]:not([data-diagram-shape="wide"]):not([data-embed="true"]):not([data-present="true"]):has(.diagram-container svg[data-input-contract="legacy-2.17"]) body { padding-block: 2px; }
  html[data-reader-layout="adaptive"]:not([data-diagram-shape="wide"]):not([data-embed="true"]):not([data-present="true"]):has(.diagram-container svg[data-input-contract="legacy-2.17"]) :is(.header, .header-row) { margin-bottom: 0; }
  html[data-reader-layout="adaptive"]:not([data-diagram-shape="wide"]):not([data-embed="true"]):not([data-present="true"]):has(.diagram-container svg[data-input-contract="legacy-2.17"]) .diagram-container { padding-top: 2px; }
  html[data-reader-layout="adaptive"]:not([data-diagram-shape="wide"]):not([data-embed="true"]):not([data-present="true"]):has(.diagram-container svg[data-input-contract="legacy-2.17"]) .diagram-nav { bottom: 4px; padding: 1px; }
}
